-- Part 6 (diversification pass): online MCQ bank (comp_mcq_questions) for civil_supervisor
-- ("سرپرست مدنی"). This role had ZERO rows in comp_mcq_questions before this seed (verified via
-- `select job_role, count(*) from comp_mcq_questions group by 1` during the audit). 40 questions,
-- APPROVED and active, spanning TECHNICAL/GENERAL/HSE/SCENARIO/JUDGMENT/PROBLEM_SOLVING/CASE_STUDY
-- and difficulty 1-3, with varied stem formats (fact-recall, "کدام گزینه نادرست است", scenario
-- best-action, and numeric/calculation items) to avoid a single predictable phrasing pattern.
-- Domain grounding: ACI 318 (concrete design/cover/lap length), ASTM C39/C143 (cube strength/
-- slump), ASTM D1557/Proctor (compaction), OSHA 1926 Subpart P/L (excavation/fall protection),
-- ACI 306/305 (hot/cold weather concreting), FIDIC-style site documentation practice.
-- Same shape/rotation technique as supabase/seed/mcq_questions_seed.sql (correct_option is
-- rotated 0..3 across rows so the answer position isn't fixed). Idempotent via
-- (job_role, md5(stem_fa)) unique index.

insert into comp_mcq_questions (job_role, category, topic, difficulty, stem_fa, options, correct_option, explanation_fa, standard_ref, approval_status, active)
select 'civil_supervisor', x ->> 0, x ->> 1, (x ->> 2)::smallint, x ->> 3,
  (select jsonb_agg(x -> 4 -> ((i - r.k + 4) % 4) order by i) from generate_series(0, 3) i),
  ((n - 1) % 4)::smallint, x ->> 6, x ->> 7, 'APPROVED', true
